            borrower = self._find_user(data["borrower"])
            lender_name = lender["name"]
            borrower_name = borrower["name"]
            amount = float(data["amount"])

            # Treat borrower -> lender as positive and lender -> borrower as
            # negative, apply the new loan, then collapse the pair to at most
            # one non-zero debt.
            net = (
                borrower["owes"].pop(lender_name, 0.0)
                - lender["owes"].pop(borrower_name, 0.0)
